-- Completes the Spain catalogue for the fourth UPR cycle: recommendations 50.41 to 50.324 of
-- A/HRC/60/8 (official Spanish text), with Spain's response from A/HRC/60/8/Add.1
-- (accepted, partially accepted or noted). 50.1 to 50.40 were loaded during the pilot.
-- Each recommendation gets what the pilot ones have: a published record, a pending
-- assessment, its human-security dimensions and a monitoring profile.
-- Safe to run again: existing records are left as they are.

create temp table upr4_import (
  n int primary key, title text, original_text text, normalized_summary text, acceptance_status text,
  news_query text, implementation_query text, boe_query text
);


create temp table upr4_import_hs (n int, code text, is_primary boolean, rationale text);


  public_id, country_id, mechanism_id, source_id, title, original_text, normalized_summary, recommendation_number,
  acceptance_status, original_language, publication_status, published_at, review_status, approved_at, approved_by
)
select 'ESP-UPR4-050.' || i.n, co.id, m.id, s.id, i.title, i.original_text, i.normalized_summary, '50.' || i.n,
  i.acceptance_status, 'es', 'published', now(), 'approved', now(), 'HRCT catalogue import'
from upr4_import i
  join public.countries co on co.iso3 = 'ESP'
  join public.mechanisms m on m.code = 'UPR'
  join public.sources s on s.document_reference = 'A/HRC/60/8'
on conflict (public_id) do nothing;

select c.id, mv.id, 'not_assessed', 'low',
  $es$Valoración del cumplimiento pendiente. Esta recomendación forma parte del catálogo público y procede del registro oficial del EPU de las Naciones Unidas; la publicación de la recomendación no implica ninguna conclusión sobre su cumplimiento.$es$,
  current_date, true, true, now()
from upr4_import i
  join public.commitments c on c.public_id = 'ESP-UPR4-050.' || i.n
  join public.methodology_versions mv on mv.version = '1.0'
where not exists (select 1 from public.assessments a where a.commitment_id = c.id);

select c.id, d.id, h.is_primary, h.rationale
from upr4_import_hs h
  join public.commitments c on c.public_id = 'ESP-UPR4-050.' || h.n
  join public.human_security_dimensions d on d.code = h.code
on conflict (commitment_id, dimension_id) do nothing;

select c.id, i.news_query, i.implementation_query, i.boe_query
from upr4_import i
  join public.commitments c on c.public_id = 'ESP-UPR4-050.' || i.n
on conflict (commitment_id) do nothing;

drop table upr4_import_hs;
drop table upr4_import;
